package com.anaiv.fluxogestao.porto;
import com.anaiv.fluxogestao.cadastro.*; import com.anaiv.fluxogestao.financeiro.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface OrdemServicoPortoRepository extends JpaRepository<OrdemServicoPorto,Long>{Optional<OrdemServicoPorto> findByNumero(String numero);List<OrdemServicoPorto> findByNumeroNormalizado(String numeroNormalizado);@Query("select os from OrdemServicoPorto os where os.motorista is null and upper(trim(os.qra))=upper(trim(:qra))")List<OrdemServicoPorto> findOrfasComQra(@Param("qra") String qra);@Query("select os from OrdemServicoPorto os where os.dataAtendimento between :inicio and :fim")List<OrdemServicoPorto> findPorAtendimentoEntre(@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);List<OrdemServicoPorto> findByNumeroIn(Collection<String> numeros);List<OrdemServicoPorto> findByOrdemPagamento(OrdemPagamentoPorto op);List<OrdemServicoPorto> findByImportacao(Importacao importacao);List<OrdemServicoPorto> findByMotorista(Motorista motorista);@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao")List<OrdemServicoPorto> findAllParaListagem();@Query("select os.ordemPagamento.id, count(os), coalesce(sum(os.valorTotal),0) from OrdemServicoPorto os where os.ordemPagamento is not null group by os.ordemPagamento.id")List<Object[]> resumirPorOrdemPagamento();@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao where os.dataAtendimento between :inicio and :fim")List<OrdemServicoPorto> findParaListagemPorAtendimento(@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);@Query("select distinct os from OrdemServicoPorto os left join fetch os.ordemPagamento op left join fetch op.calendarioPagamento left join fetch op.importacao left join fetch os.motorista left join fetch os.importacao where os.dataEfetivaPagamento between :inicio and :fim")List<OrdemServicoPorto> findParaListagemPorPagamento(@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);long countByDataAtendimentoBetween(LocalDate inicio,LocalDate fim);@Query("select max(os.dataAtendimento) from OrdemServicoPorto os")LocalDate maiorDataAtendimento();@Query("select os from OrdemServicoPorto os left join fetch os.ordemPagamento where os.motorista is null")List<OrdemServicoPorto> findSemMotorista();@Query("select os.numero from OrdemServicoPorto os where os.numero in :numeros")List<String> numerosExistentes(@Param("numeros") Collection<String> numeros);@Query("select distinct os from OrdemServicoPorto os join fetch os.ordemPagamento op where os.motorista in :motoristas and op.calendarioPagamento=:periodo and op.situacaoFinanceira=:situacaoOp and os.statusFinanceiro=:statusOs order by os.dataAtendimento, os.numero")List<OrdemServicoPorto> findPagasNoPeriodo(@Param("motoristas") Collection<Motorista> motoristas,@Param("periodo") CalendarioPagamentoPorto periodo,@Param("situacaoOp") EnumsFinanceiros.SituacaoFinanceiraOpPorto situacaoOp,@Param("statusOs") EnumsFinanceiros.StatusFinanceiroPorto statusOs);}
